package dev.aragonite.powersync.client;
import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;
final class ServerClient {
 static JSONObject redeem(String base,String code,String installation,String nativeDevice,String nativeUid)throws Exception {JSONObject body=new JSONObject().put("code",code).put("installationId",installation).put("nativeDeviceId",nativeDevice).put("model",android.os.Build.MODEL).put("nativeUid",nativeUid).put("preserveNativeIdentity",true);return request(base+"/api/v1/boox/enroll","POST",body,null);}
 static JSONObject request(String url,String method,JSONObject body,String token)throws Exception {return request(url,method,body,token,262144);}
 static JSONObject request(String url,String method,JSONObject body,String token,int limit)throws Exception {HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();if(!"https".equals(c.getURL().getProtocol()))throw new UserError(R.string.error_https_required);c.setConnectTimeout(15000);c.setReadTimeout(15000);c.setInstanceFollowRedirects(false);c.setRequestMethod(method);if(token!=null)c.setRequestProperty("Authorization","Bearer "+token);c.setRequestProperty("Accept-Language",java.util.Locale.getDefault().toLanguageTag());try{if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes(StandardCharsets.UTF_8));}}int status=c.getResponseCode();if(status==409){if(!url.endsWith("/api/v1/boox/enroll"))throw new UserError(R.string.error_server_data_changed_or_recovery_is_unavailable);try(InputStream error=c.getErrorStream()){if(error!=null){byte[] raw=error.readNBytes(4096);JSONObject detail=new JSONObject(new String(raw,StandardCharsets.UTF_8));if("native_identity_required".equals(detail.optString("error")))throw new UserError(R.string.error_sign_in_to_your_boox_account_in);}}throw new UserError(R.string.error_this_server_is_linked_to_a_different);}if(status<200||status>=300)throw new UserError(R.string.error_server_http_status,status);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>limit)throw new UserError(R.string.error_server_reply_exceeds_limit);out.write(b,0,n);}return new JSONObject(new String(out.toByteArray(),StandardCharsets.UTF_8));}}finally{c.disconnect();}}
}
